#include "geometry_pose_file_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("test scratch path required");std::vector<uint8_t>bytes(100);uint32_t count=2;std::memcpy(bytes.data(),&count,4);auto write=[&](const std::vector<uint8_t>&data){std::ofstream file(argv[1],std::ios::binary);file.write(reinterpret_cast<const char*>(data.data()),std::streamsize(data.size()));file.close();if(!file)throw std::runtime_error("scratch write");};write(bytes);auto valid=readGeometryPoseFileCandidate(argv[1],2);if(valid.size()!=2||std::memcmp(valid.data(),bytes.data()+4,96))throw std::runtime_error("pose bytes changed");size_t rejected=0;auto reject=[&](auto data){write(data);try{readGeometryPoseFileCandidate(argv[1],2);}catch(const std::runtime_error&){++rejected;}};auto changed=bytes;changed[0]=3;reject(changed);changed=bytes;changed.pop_back();reject(changed);changed=bytes;changed.push_back(0);reject(changed);changed=bytes;float invalid=std::numeric_limits<float>::quiet_NaN();std::memcpy(changed.data()+4,&invalid,4);reject(changed);if(rejected!=4)throw std::runtime_error("pose rejection");std::cout<<"x64 pose file validation passed rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
